// reproduce.js
// A small standalone script that shows data URIs still get a nonzero serverResponseTime

const path = require('path');
// Adjust this to point at your local checkout of Lighthouse
const Simulator = require('lighthouse/lighthouse-core/lib/dependency-graph/simulator/simulator.js');
const NetworkNode = require('lighthouse/lighthouse-core/lib/dependency-graph/network-node.js');

// 1) Build a mock network request for a data URI
const dataUriRecord = {
  requestId: 1,
  url: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAUA',
  parsedURL: {scheme: 'data', host: '', securityOrigin: 'data'},
  transferSize: 100,
  timing: {},
  resourceType: 'Image',
  fromDiskCache: false,
};

// 2) Wrap it in a NetworkNode and run the simulator
const rootNode = new NetworkNode(dataUriRecord);
const simulator = new Simulator({ /* no precomputed lantern data */ });
const result = simulator.simulate(rootNode);

// 3) Inspect the connection pool options that were applied for "data"
const pool = simulator._connectionPool;
const originKey = dataUriRecord.parsedURL.securityOrigin;
const rttByOrigin = pool._options.additionalRttByOrigin.get(originKey) || 0;
const serverResponseByOrigin = pool._options.serverResponseTimeByOrigin.get(originKey);

console.log('Data URI origin:', originKey);
console.log('additionalRttByOrigin:', rttByOrigin);
console.log('serverResponseTimeByOrigin:', serverResponseByOrigin);
// You will see serverResponseTimeByOrigin !== 0 (it defaults to 30 ms),
// even though data URIs should never incur server latency.
